alter table zakat_methods enable row level security; alter table currencies enable row level security; alter table market_prices enable row level security; alter table fx_rates enable row level security; alter table zakat_rules enable row level security; alter table sharia_rule_reviews enable row level security; alter table rule_sources enable row level security; alter table notification_jobs enable row level security; alter table price_provider_configs enable row level security;
create or replace function public.schedule_hawl_notifications(p_user uuid) returns integer language plpgsql security invoker set search_path=public as $$ declare r record; n integer:=0; d integer; v_ts timestamptz; begin for r in select id,hawl_due_date from lots where user_id=p_user and remaining_quantity>0 and hawl_due_date is not null loop foreach d in array ARRAY[30,15,7]::integer[] loop v_ts:=(r.hawl_due_date-make_interval(days=>d))::timestamptz; insert into notification_jobs(user_id,notification_type,scheduled_for) values(p_user,'HAWL_DUE_'||d,v_ts) on conflict do nothing; n:=n+1; end loop; end loop; return n; end; $$;
revoke execute on function public.handle_new_user() from anon,authenticated; revoke execute on function public.has_role(uuid,text[]) from anon,authenticated;
